import csv

with open('contacts.csv', newline='') as f:
    rows = list(csv.DictReader(f))

best = {}
for r in rows:
    email = r['email'].strip().lower()
    cur = best.get(email)
    # Strict '<' keeps the first-appearing row on a tie.
    if cur is None or r['created'] < cur['created']:
        best[email] = {'name': r['name'], 'email': email, 'created': r['created']}

out = sorted(best.values(), key=lambda x: (x['created'], x['email']))

with open('clean.csv', 'w', newline='') as f:
    w = csv.writer(f, lineterminator='\n')
    w.writerow(['name', 'email', 'created'])
    for x in out:
        w.writerow([x['name'], x['email'], x['created']])
